const msg = $input.first().json.message || {};
const text = (msg.text || '').trim();
const chatId = msg.chat?.id;
const name = msg.from?.first_name || 'amigo';
const username = msg.from?.username || name;
const userId = msg.from?.id;
const lower = text.toLowerCase();

// ===== COMANDOS =====
if (text.startsWith('/')) {
  const cmd = lower.split(' ')[0].replace('@','').split('/')[1];

  if (cmd === 'start') {
    return [{ json: { chatId, type: 'static', text: `🎮 <b>¡Bienvenido a ApexTournament, ${name}!</b>

Soy tu asistente para torneos de eSports.

💬 <b>¡Puedes hablarme de forma natural!</b>
Pregúntame lo que quieras sobre torneos, rankings o partidas.

<b>📋 Comandos rápidos:</b>
/torneos - Ver torneos activos
/ranking - Ver top 10 jugadores
/stats - Ver tus estadísticas
/proximas - Ver próximas partidas
/juegos - Ver juegos disponibles
/ayuda - Mostrar ayuda completa

<b>💡 Ejemplos de preguntas:</b>
• "¿Hay torneos disponibles?"
• "¿Quién va primero en el ranking?"
• "¿Qué partidas hay ahora?"

<i>¡Buena suerte en tus competencias!</i>` }}];
  }

  if (cmd === 'ayuda' || cmd === 'help') {
    return [{ json: { chatId, type: 'static', text: `📖 <b>Ayuda - ApexTournament Bot</b>

🤖 <b>¡Soy un bot conversacional!</b>
Puedes hablarme de forma natural o usar comandos.

<b>🎮 Comandos de Torneos:</b>
/torneos - Ver torneos con registro abierto

<b>📊 Comandos de Estadísticas:</b>
/ranking - Ver top 10 jugadores
/stats - Ver tus estadísticas

<b>⚔️ Comandos de Partidas:</b>
/proximas - Ver próximas partidas
/envivo - Ver partidas en vivo

<b>🛡️ Comandos de Clanes:</b>
/clanes - Ver lista de equipos
/miclan - Ver mi estatus

<b>💡 ¿Cómo vincular mi cuenta?</b>
Abre la app → Configuración → Conectar Telegram` }}];
  }

  if (cmd === 'reglas') {
    return [{ json: { chatId, type: 'static', text: `📜 <b>Reglas Generales de ApexTournament</b>

<b>1. Conducta:</b>
• Respeto hacia todos los participantes
• No se tolera el acoso o comportamiento tóxico
• Fair play en todas las partidas

<b>2. Partidas:</b>
• Estar disponible 15 min antes
• Notificar ausencias con anticipación

<b>3. Desconexiones:</b>
• Primera vez: oportunidad de reconexión (5 min)
• Más de una: puede resultar en descalificación

<b>4. Trampas:</b>
• Tolerancia cero hacia hacks o exploits
• Sanción: ban permanente

<b>5. Disputas:</b>
• Los administradores tienen la palabra final

<i>¿Dudas? Contacta a un moderador.</i>` }}];
  }

  if (cmd === 'torneos') return [{ json: { chatId, type: 'db', query: 'torneos', userId } }];
  if (cmd === 'ranking') return [{ json: { chatId, type: 'db', query: 'ranking', userId } }];
  if (cmd === 'juegos') return [{ json: { chatId, type: 'db', query: 'juegos', userId } }];
  if (cmd === 'proximas') return [{ json: { chatId, type: 'db', query: 'proximas', userId } }];
  if (cmd === 'envivo') return [{ json: { chatId, type: 'db', query: 'envivo', userId } }];
  if (cmd === 'stats') return [{ json: { chatId, type: 'db', query: 'stats', userId } }];
  if (cmd === 'clanes') return [{ json: { chatId, type: 'db', query: 'clanes', userId } }];
  if (cmd === 'miclan') return [{ json: { chatId, type: 'db', query: 'miclan', userId } }];

  return [{ json: { chatId, type: 'static', text: '🤔 Comando no reconocido. Usa /ayuda para ver los comandos disponibles.' }}];
}

// ===== PATRONES CONVERSACIONALES =====
const patterns = [
  { r: /^(hola|hey|buenas|buenos d[ií]as|buenas tardes|buenas noches|saludos|hi|hello|que tal|qué tal|holi)/i, resp: [`¡Hola ${name}! 👋 ¿En qué puedo ayudarte?
Usa /ayuda para ver los comandos.`, `¡Hey ${name}! 🎮 ¿Qué tal?`] },
  { r: /^(adi[oó]s|bye|chao|hasta luego|nos vemos|me voy)/i, resp: [`¡Hasta luego ${name}! 👋`, `¡Nos vemos ${name}! 🎮`] },
  { r: /^(gracias|thanks|thx|muchas gracias)/i, resp: [`¡De nada ${name}! 😊`, `¡Con gusto! 🎮`] },
  { r: /qu[eé] (puedes|sabes|haces|eres)|para qu[eé] sirves|qu[eé] comandos/i, resp: ['¡Soy el bot de ApexTournament! 🤖
Usa /ayuda para ver todo lo que puedo hacer.'] },
  { r: /hay (alg[uú]n )?torneo|torneos?|quiero (jugar|participar)|c[oó]mo (participo|me uno)/i, resp: ['🏆 Usa /torneos para ver los torneos disponibles.'] },
  { r: /ranking|clasificaci[oó]n|mejores jugadores|qui[eé]n va ganando/i, resp: ['📊 Usa /ranking para ver el top 10.'] },
  { r: /partidas? (en vivo|ahora)|qui[eé]n (juega|est[aá] jugando)/i, resp: ['⚔️ Usa /envivo o /proximas'] },
  { r: /mis (stats|estad[ií]sticas)|c[oó]mo voy|mi rating/i, resp: ['📈 Usa /stats para ver tus estadísticas.'] },
  { r: /qu[eé] juegos|juegos disponibles/i, resp: ['🎮 Usa /juegos'] },
  { r: /reglas|normas/i, resp: ['📜 Usa /reglas'] },
  { r: /problema|no funciona|ayuda|help|necesito ayuda/i, resp: ['🆘 ¿Puedes decirme más sobre tu problema?'] },
  { r: /gan[eé]|victoria|genial|incre[ií]ble|wow/i, resp: [`¡Felicidades ${name}! 🎉🏆`] },
  { r: /c[oó]mo est[aá]s|qu[eé] tal|todo bien/i, resp: [`¡Todo bien ${name}! 🤖 ¿Necesitas algo?`] },
  { r: /clan|equipo|team/i, resp: ['👥 La gestión de clanes se hace desde la web. Usa /clanes para verlos.'] }
];

for (const p of patterns) {
  if (p.r.test(lower)) {
    const resp = p.resp[Math.floor(Math.random() * p.resp.length)];
    return [{ json: { chatId, type: 'static', text: resp }}];
  }
}

// ===== SI NADA COINCIDE → IA =====
return [{ json: { chatId, type: 'ai', text: text, userId } }];

const data = $input.first().json;
const query = data.query;
const userId = data.userId;

const queries = {
  torneos: "SELECT t.name, t.status, t.start_date, t.prize_pool, g.name as game_name FROM tournaments t LEFT JOIN games g ON t.game_id = g.id WHERE t.status IN ('REGISTRATION_OPEN', 'PUBLISHED', 'IN_PROGRESS') ORDER BY t.start_date ASC LIMIT 10",
  ranking: "SELECT ps.rating, ps.wins, ps.losses, u.username, g.name as game_name FROM player_stats ps JOIN users u ON ps.user_id = u.id JOIN games g ON ps.game_id = g.id ORDER BY ps.rating DESC LIMIT 10",
  juegos: "SELECT name, team_size_default FROM games ORDER BY name ASC",
  proximas: "SELECT m.scheduled_datetime, t.name as tournament_name, ht.name as home_team, at2.name as away_team FROM matches m JOIN tournaments t ON m.tournament_id = t.id LEFT JOIN teams ht ON m.home_team_id = ht.id LEFT JOIN teams at2 ON m.away_team_id = at2.id WHERE m.status = 'SCHEDULED' AND m.scheduled_datetime >= NOW() ORDER BY m.scheduled_datetime ASC LIMIT 5",
  envivo: "SELECT m.home_score, m.away_score, t.name as tournament_name, ht.name as home_team, at2.name as away_team FROM matches m JOIN tournaments t ON m.tournament_id = t.id LEFT JOIN teams ht ON m.home_team_id = ht.id LEFT JOIN teams at2 ON m.away_team_id = at2.id WHERE m.status = 'LIVE' LIMIT 10",
  stats: `SELECT u.username, ps.rating, ps.wins, ps.losses, g.name as game_name FROM users u LEFT JOIN player_stats ps ON ps.user_id = u.id LEFT JOIN games g ON ps.game_id = g.id WHERE u.telegram_chat_id = '${userId}' LIMIT 20`,
  clanes: "SELECT c.name, c.tag, u.username as leader_name, (SELECT COUNT(*) FROM clan_members WHERE clan_id = c.id) as member_count FROM clans c JOIN users u ON c.leader_id = u.id ORDER BY c.created_at DESC LIMIT 10",
  miclan: `SELECT c.name, c.tag, cm.role, cm.joined_at FROM users u JOIN clan_members cm ON cm.user_id = u.id JOIN clans c ON cm.clan_id = c.id WHERE u.telegram_chat_id = '${userId}' LIMIT 1`
};

return [{ json: { sql: queries[query] || 'SELECT 1', query, chatId: data.chatId, userId } }];

const queryType = $('Build Query').first().json.query;
const rows = $input.all().map(i => i.json);

let msg = '';

switch(queryType) {
  case 'torneos': {
    if (rows.length === 0 || !rows[0].name) { msg = '😔 No hay torneos activos en este momento.'; break; }
    msg = '🏆 <b>Torneos Disponibles:</b>\n\n';
    rows.forEach(t => {
      const emoji = t.status === 'IN_PROGRESS' ? '🔴' : t.status === 'REGISTRATION_OPEN' ? '🟢' : '🟡';
      const st = t.status === 'IN_PROGRESS' ? 'En Curso' : t.status === 'REGISTRATION_OPEN' ? 'Registro Abierto' : 'Próximamente';
      msg += `${emoji} <b>${t.name}</b>\n   🎮 ${t.game_name||'Varios'} | 💰 $${t.prize_pool||0} | ${st}\n\n`;
    });
    break;
  }
  case 'ranking': {
    if (rows.length === 0 || !rows[0].username) { msg = '😔 No hay jugadores en el ranking.'; break; }
    const medals = ['🥇','🥈','🥉'];
    msg = '🏅 <b>Top 10 Jugadores:</b>\n\n';
    rows.forEach((s,i) => {
      const m = medals[i] || `${i+1}.`;
      const wr = s.wins+s.losses > 0 ? Math.round((s.wins/(s.wins+s.losses))*100) : 0;
      msg += `${m} <b>${s.username}</b> ⭐${s.rating} | ${s.wins}W/${s.losses}L (${wr}%)\n`;
    });
    break;
  }
  case 'juegos': {
    if (rows.length === 0 || !rows[0].name) { msg = '😔 No hay juegos registrados.'; break; }
    msg = '🎮 <b>Juegos Disponibles:</b>\n\n';
    rows.forEach(g => { msg += `• <b>${g.name}</b> (${g.team_size_default} jugadores)\n`; });
    break;
  }
  case 'proximas': {
    if (rows.length === 0 || !rows[0].tournament_name) { msg = '📅 No hay partidas programadas.'; break; }
    msg = '⚔️ <b>Próximas Partidas:</b>\n\n';
    rows.forEach(m => {
      const time = m.scheduled_datetime ? new Date(m.scheduled_datetime).toLocaleString('es-MX',{dateStyle:'short',timeStyle:'short'}) : 'TBD';
      msg += `🏆 <b>${m.tournament_name}</b>\n   ${m.home_team||'TBD'} 🆚 ${m.away_team||'TBD'} | 🕐 ${time}\n\n`;
    });
    break;
  }
  case 'envivo': {
    if (rows.length === 0 || !rows[0].tournament_name) { msg = '📺 No hay partidas en vivo.\nUsa /proximas.'; break; }
    msg = '🔴 <b>EN VIVO:</b>\n\n';
    rows.forEach(m => { msg += `🏆 ${m.tournament_name}: ${m.home_team||'TBD'} <b>${m.home_score||0}-${m.away_score||0}</b> ${m.away_team||'TBD'}\n`; });
    break;
  }
  case 'stats': {
    if (rows.length === 0 || !rows[0].username) { msg = '📊 <b>Estadísticas</b>\n\n❌ Tu cuenta no está vinculada.\n\n1. Abre ApexTournament\n2. Ve a Configuración → Notificaciones\n3. Conecta tu Telegram'; break; }
    const u = rows[0];
    let tw=0,tl=0,tr=0;
    rows.filter(r=>r.rating).forEach(s=>{tw+=s.wins||0;tl+=s.losses||0;tr=Math.max(tr,s.rating||0);});
    const wr = tw+tl>0 ? Math.round((tw/(tw+tl))*100) : 0;
    msg = `📊 <b>Estadísticas de ${u.username}</b>\n\n⭐ Rating: ${tr} | 🏆 ${tw}W/${tl}L (${wr}%)`;
    rows.filter(r=>r.game_name).forEach(s=>{ msg += `\n• ${s.game_name}: ${s.wins||0}W/${s.losses||0}L`; });
    break;
  }
  case 'clanes': {
    if (rows.length === 0 || !rows[0].name) { msg = '😔 No hay clanes registrados.'; break; }
    msg = '🛡️ <b>Clanes:</b>\n\n';
    rows.forEach(c => { msg += `🔹 <b>${c.name}</b> [${c.tag||''}] 👑${c.leader_name} 👥${c.member_count}\n`; });
    break;
  }
  case 'miclan': {
    if (rows.length === 0 || !rows[0].name) { msg = '❌ No perteneces a ningún clan o tu cuenta no está vinculada.'; break; }
    const cm = rows[0];
    msg = `🛡️ <b>Mi Clan: ${cm.name}</b> [${cm.tag||''}]\n👮 Rol: ${cm.role}`;
    break;
  }
  default: msg = '❌ Error procesando comando.';
}

return [{ json: { text: msg, chatId: $('Build Query').first().json.chatId }}];

const userText = $input.first().json.text || '';
const chatId = $input.first().json.chatId;

const apiKey = 'AIzaSyBaz8GjHnE3FaAQbJf8xmpT8QRLhOI9qmY';
const models = ['gemini-2.0-flash-lite', 'gemini-2.0-flash'];

const prompt = `Eres ApexBot, asistente de torneos eSports de ApexTournament.\n\nPREGUNTA: ${userText}\n\nINSTRUCCIONES: Responde amigable, conciso, en español, con emojis. Máximo 3 párrafos. No inventes datos. Si preguntan por torneos sugiere /torneos, por ranking sugiere /ranking.\n\nRESPUESTA:`;

for (const model of models) {
  try {
    const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`;
    const response = await this.helpers.httpRequest({
      method: 'POST',
      url: url,
      body: { contents: [{ parts: [{ text: prompt }] }] },
      headers: { 'Content-Type': 'application/json' },
      json: true
    });
    if (response.candidates && response.candidates[0]) {
      const text = response.candidates[0].content.parts[0].text;
      return [{ json: { chatId, text } }];
    }
  } catch (e) {
    // try next model
  }
}

